        "/work/freyja_aggregate_plot/abundances_dashboard.html",
        "&&",
        "freyja",
        "plot",
        "--lineages",
        "--mincov",
        "75",
        "/work/freyja_aggregate_plot/aggregated.tsv",
        "--output",
        "/work/freyja_aggregate_plot/abundances_plot.pdf",
        "--times",
