        "window=30.0",
        "overlap=3.0",
        "seed=42",
        "err=0.02",
        "burnin=4",
        "iterations=10",
        "phase-states=250",
        "impute=false",
        "imp-states=1200",
        "imp-segment=5.0",
        "imp-step=0.2",
        "cluster=0.01",
        "ap=true",
        "gp=true",
        "out=/work/beagle/out",
        "nthreads=${GALAXY_SLOTS:-8}",
        "&&",
        "gunzip",
        "/work/beagle/out.vcf.gz",
        "&&",
        "mv",
        "/work/beagle/out.vcf",
