        "--cpus",
        "8",
        "--min_perc_aa",
        "15",
        "--force",
        "--min_af",
        "0.7",
        "--full_tree",
        "--skip_ani_screen",
        "&&",
        "cat",
        "/work/gtdbtk/output_dir/gtdbtk.warnings.log",
