def test_bedops_sort_bed_renders_sort_unique_and_duplicate_commands(tmp_path: Path) -> None:
    node_class = _node_class("bedops_sort_bed")

    assert node_class.render_command(
        {
            "inputs": ["sample.bed"],
            "memory_mb": 2048,
            "tmpdir": "/scratch/job",
            "output": "/work/bedops_sort_bed",
        }
    ) == [
        "sort-bed",
        "--max-mem",
        "2048M",
        "--tmpdir",
        "/scratch/job",
        "sample.bed",
        ">",
        "/work/bedops_sort_bed/sorted.bed",
    ]

    assert node_class.render_command(
        {
            "inputs": ["a.bed", "b.bed"],
            "unique": True,
            "memory_mb": 1024,
            "output": "/work/bedops_sort_bed",
        }
    ) == [
        "sort-bed",
        "--max-mem",
        "1024M",
        "--tmpdir",
        ".",
        "--unique",
        "a.bed",
        "b.bed",
        ">",
        "/work/bedops_sort_bed/sorted.bed",
    ]

    assert node_class.render_command(
        {
            "inputs": ["a.bed", "b.bed"],
            "duplicates": True,
            "memory_mb": 512,
            "output": "/work/bedops_sort_bed",
        }
    ) == [
        "sort-bed",
        "--max-mem",
        "512M",
        "--tmpdir",
        ".",
        "--duplicates",
        "a.bed",
        "b.bed",
        ">",
        "/work/bedops_sort_bed/sorted.bed",
    ]

    assert node_class.PLAN_OUTPUTS({}, tmp_path) == [tmp_path / "bedops_sort_bed" / "sorted.bed"]


