    assert node_class.VALIDATE_INPUTS({"input_file": "mpileup.vcf", "method": "multiallelic"}) is True
    assert (
        node_class.VALIDATE_INPUTS(
            {
                "input_file": "mpileup.vcf",
                "method": "multiallelic",
                "constrain": "none",
                "gvcf": "",
                "prior": "",
                "novel_rate_snp": "",
                "novel_rate_del": "",
                "novel_rate_ins": "",
                "pval_threshold": "",
            }
        )
        is True
    )


